module.exports = "<section class=\"bmb_notice-card\">\n  <section class=\"bmb_notice-card-header\">\n    <figure class=\"bmb_notice-card-header-figure\">\n      <picture>\n        <source media=\"(min-width: 1000px)\" [srcset]=\"src()\" />\n        <img\n          [loading]=\"'lazy'\"\n          class=\"bmb_notice-card-header-image\"\n          [srcset]=\"src()\"\n          [alt]=\"title()\"\n          [loading]=\"'lazy'\"\n        />\n      </picture>\n    </figure>\n    <bmb-action-icon\n      class=\"bmb_notice-card-header-icon\"\n      [ngStyle]=\"{\n        color:\n          closeBtnColor() == 'white'\n            ? 'RGBA(var(--color-charade-50))'\n            : 'RGBA(var(--color-charade-950))'\n      }\"\n      [icon]=\"'close'\"\n      [iconSize]=\"28\"\n      (buttonClick)=\"handleClose()\"\n    />\n  </section>\n  <section class=\"bmb_notice-card-content\">\n    <div class=\"bmb_notice-card-content-title\">\n      <h3>{{ title() }}</h3>\n    </div>\n    @if (activeIndex == 0) {\n      <div class=\"bmb_notice-card-content-description-one\">\n        <p class=\"bmb_notice-card-content-description-text\">\n          {{ description()?.pageOne }}\n        </p>\n      </div>\n    }\n    @if (description()!.pageTwo && activeIndex === 1) {\n      <div class=\"bmb_notice-card-content-description-two\">\n        <p class=\"bmb_notice-card-content-description-text\">\n          {{ description()?.pageTwo }}\n        </p>\n      </div>\n    }\n  </section>\n  <div class=\"bmb_notice-card-divider\">\n    <bmb-divider [type]=\"'simple'\"></bmb-divider>\n  </div>\n  <section class=\"bmb_notice-card-footer\">\n    <div class=\"bmb_notice-card-footer-left\">\n      @if (description()!.pageTwo && activeIndex === 1) {\n        <bmb-action-icon\n          [icon]=\"'chevron_left'\"\n          [iconSize]=\"28\"\n          (buttonClick)=\"onDotPress(0)\"\n        />\n      }\n    </div>\n\n    <div class=\"bmb_notice-card-footer-center\">\n      @if (\n        (description()!.pageTwo && activeIndex === 1) || !description()!.pageTwo\n      ) {\n        @if (link()) {\n          <a\n            class=\"bmb_notice-card-footer-center-link\"\n            [href]=\"link()\"\n            target=\"_blank\"\n            rel=\"noopener noreferrer\"\n          >\n            <button\n              bmbButton\n              [appearance]=\"'secondary-outlined'\"\n              [size]=\"'large'\"\n              (click)=\"handleClickBtn()\"\n            >\n              {{ buttonText() || ('notice_card.button_text' | translate) }}\n            </button>\n          </a>\n        } @else {\n          <button\n            bmbButton\n            [appearance]=\"'secondary-outlined'\"\n            [size]=\"'large'\"\n            (click)=\"handleClickBtn()\"\n          >\n            {{ buttonText() || ('notice_card.button_text' | translate) }}\n          </button>\n        }\n      }\n\n      @if (description()!.pageTwo && activeIndex === 0) {\n        <bmb-dot-paginator\n          [activeDotIndex]=\"activeIndex\"\n          [totalDots]=\"2\"\n          (onDotPress)=\"onDotPress($event)\"\n        ></bmb-dot-paginator>\n      }\n    </div>\n\n    <div class=\"bmb_notice-card-footer-right\">\n      @if (description()!.pageTwo && activeIndex === 0) {\n        <bmb-action-icon\n          class=\"bmb_notice-card-footer-right\"\n          [icon]=\"'chevron_right'\"\n          [iconSize]=\"28\"\n          (buttonClick)=\"onDotPress(1)\"\n        />\n      }\n    </div>\n  </section>\n</section>\n";

